/**
 * Tree styles — port of charmbracelet/bubbles/tree/styles.go (v2.2.1).
 *
 * @module
 */

import { newStyle, lightDark } from '@oakoliver/lipgloss';
import type { Style } from '@oakoliver/lipgloss';
import type { Nodes } from './node.js';

/** StyleFunc allows the tree to be styled per item. */
export type StyleFunc = (children: Nodes, i: number) => Style;

/**
 * Style definitions for the tree component. By default, these values are
 * generated by {@link defaultStyles}. The optional `*StyleFunc` fields take
 * precedence over their static counterparts when set.
 */
export interface Styles {
  treeStyle: Style;
  helpStyle: Style;

  selectedNodeStyle: Style;
  selectedNodeStyleFunc?: StyleFunc | null;

  nodeStyle: Style;
  nodeStyleFunc?: StyleFunc | null;

  rootNodeStyle: Style;
  rootNodeStyleFunc?: StyleFunc | null;

  parentNodeStyle: Style;
  parentNodeStyleFunc?: StyleFunc | null;

  cursorStyle: Style;

  enumeratorStyle: Style;
  enumeratorStyleFunc?: StyleFunc | null;

  selectedEnumeratorStyle: Style;
  selectedEnumeratorStyleFunc?: StyleFunc | null;

  indenterStyle: Style;
  indenterStyleFunc?: StyleFunc | null;

  openIndicatorStyle: Style;
}

/**
 * Styles with the effective per-item style functions resolved (the Go
 * version's unexported `*Func` fields).
 *
 * @internal
 */
export interface ResolvedStyles extends Styles {
  readonly _selectedNodeFunc: StyleFunc;
  readonly _nodeFunc: StyleFunc;
  readonly _rootNodeFunc: StyleFunc;
  readonly _parentNodeFunc: StyleFunc;
  readonly _enumeratorFunc: StyleFunc;
  readonly _selectedEnumeratorFunc: StyleFunc;
  readonly _indenterFunc: StyleFunc;
}

/**
 * Resolves the effective style functions: a user-provided `*StyleFunc` wins,
 * otherwise the static style is returned for every item.
 *
 * @internal
 */
export function resolveStyles(styles: Styles): ResolvedStyles {
  const s: Styles = { ...styles };
  return {
    ...s,
    _nodeFunc: s.nodeStyleFunc ?? (() => s.nodeStyle),
    _selectedNodeFunc: s.selectedNodeStyleFunc ?? (() => s.selectedNodeStyle),
    _parentNodeFunc: s.parentNodeStyleFunc ?? (() => s.parentNodeStyle),
    _rootNodeFunc: s.rootNodeStyleFunc ?? (() => s.rootNodeStyle),
    _enumeratorFunc: s.enumeratorStyleFunc ?? (() => s.enumeratorStyle),
    _selectedEnumeratorFunc: s.selectedEnumeratorStyleFunc ?? (() => s.selectedEnumeratorStyle),
    _indenterFunc: s.indenterStyleFunc ?? (() => s.indenterStyle),
  };
}

/** Returns a set of default style definitions for the tree component. */
export function defaultStyles(isDark: boolean): Styles {
  const ld = lightDark(isDark);
  const verySubduedColor = ld('#DDDADA', '#3C3C3C');
  const subduedColor = ld('#9B9B9B', '#5C5C5C');

  const nodeStyle = newStyle().foreground(ld('#9B9B9B', '#B0B0B0'));
  const enumeratorStyle = newStyle().foreground(verySubduedColor);

  return {
    treeStyle: newStyle(),
    helpStyle: newStyle().paddingTop(1),
    nodeStyle,
    selectedNodeStyle: nodeStyle.foreground(ld('249', '212')).bold(true),
    rootNodeStyle: newStyle().foreground(ld('#EE6FF8', '#EE6FF8')),
    parentNodeStyle: newStyle().foreground(ld('90', '99')),
    cursorStyle: newStyle().paddingRight(1).foreground(ld('249', '212')).bold(true),
    enumeratorStyle,
    selectedEnumeratorStyle: enumeratorStyle,
    indenterStyle: newStyle().foreground(verySubduedColor),
    openIndicatorStyle: newStyle().foreground(subduedColor),
  };
}

/** Returns a set of default styles for dark backgrounds. */
export function defaultDarkStyles(): Styles {
  return defaultStyles(true);
}

/** Returns a set of default styles for light backgrounds. */
export function defaultLightStyles(): Styles {
  return defaultStyles(false);
}
